code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A vertical 5-bar carries the colored tile immediately to its right
    # along the length of the bar.
    by_col = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                by_col.setdefault(c, []).append(r)
    for c, rows in by_col.items():
        rows.sort()
        runs = []
        run = []
        for r in rows:
            if run and r != run[-1] + 1:
                runs.append(run); run = []
            run.append(r)
        if run: runs.append(run)
        for run in runs:
            if len(run) < 2 or c + 1 >= w:
                continue
            r0, r1 = run[0], run[-1]
            cells = [(r, x) for r in range(h) for x in range(c + 1, w)
                     if grid[r][x] not in (0, 5)]
            if not cells:
                continue
            sr0 = min(r for r, x in cells); sr1 = max(r for r, x in cells)
            sc0 = min(x for r, x in cells); sc1 = max(x for r, x in cells)
            tile = [[grid[r][x] for x in range(sc0, sc1 + 1)]
                    for r in range(sr0, sr1 + 1)]
            th, tw = len(tile), len(tile[0])
            for r in range(r0, r1 + 1):
                ti = (th - 1 + r - r1) % th
                for x in range(sc0, sc1 + 1):
                    v = tile[ti][(x - sc0) % tw]
                    if v:
                        out[r][x] = v

    # A horizontal 5-bar carries the colored column below it across its span.
    by_row = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                by_row.setdefault(r, []).append(c)
    for r, cols in by_row.items():
        cols.sort()
        runs = []
        run = []
        for c in cols:
            if run and c != run[-1] + 1:
                runs.append(run); run = []
            run.append(c)
        if run: runs.append(run)
        for run in runs:
            if len(run) < 2 or r + 1 >= h:
                continue
            c0, c1 = run[0], run[-1]
            cells = [(y, c) for y in range(r + 1, h) for c in range(c0, c1 + 1)
                     if grid[y][c] not in (0, 5)]
            if not cells:
                continue
            sr0 = min(y for y, c in cells); sr1 = max(y for y, c in cells)
            sc0 = min(c for y, c in cells); sc1 = max(c for y, c in cells)
            tile = [[grid[y][c] for c in range(sc0, sc1 + 1)]
                    for y in range(sr0, sr1 + 1)]
            th, tw = len(tile), len(tile[0])
            for y in range(sr0, sr1 + 1):
                for c in range(c0, c1 + 1):
                    v = tile[y - sr0][(c - c0) % tw]
                    if v:
                        out[y][c] = v
    return out
'''
